  6	type Reply = {
  7	  status?: number;
  8	  body?: string;
  9	  json?: unknown;
 10	  contentType?: string;
 11	};
 12	type BackendRoute = {
 13	  request(): { url(): string };
 14	  fulfill(reply: Reply): Promise<void>;
 15	};
 16	export class Backend {
 17	  handlers: { pattern: string; handle: (route: BackendRoute) => unknown }[] =
 18	    [];
 19	  waiters: {
 20	    predicate: (request: { url(): string }) => boolean;
 21	    resolve: () => void;
 22	  }[] = [];
 23	  async route(pattern: string, handle: (route: BackendRoute) => unknown) {
 24	    this.handlers.push({ pattern, handle });
 25	  }
 26	  async unroute(pattern: string) {
 27	    this.handlers = this.handlers.filter(
 28	      (handler) => handler.pattern !== pattern,
 29	    );
 30	  }
 31	  waitForRequest(predicate: (request: { url(): string }) => boolean) {
 32	    return new Promise<void>((resolve) =>
 33	      this.waiters.push({ predicate, resolve }),
 34	    );
 35	  }
 36	  async respond(url: string, response: ServerResponse) {
 37	    const request = { url: () => url };
 38	    for (const waiter of this.waiters)
 39	      if (waiter.predicate(request)) waiter.resolve();
 40	    const handler = this.handlers.findLast(({ pattern }) =>
 41	      new RegExp(
 42	        "^" +
 43	          pattern
 44	            .split("*")
 45	            .map((part) => part.replace(/[.+?^${}()|[\]\\]/g, "\\$&"))
 46	            .join(".*") +
 47	          "$",
 48	      ).test(url),
 49	    );
 50	    if (!handler) {
 51	      response.writeHead(404).end();
 52	      return;
 53	    }
 54	    await handler.handle({
 55	      request: () => request,
 56	      fulfill: async ({ status = 200, body, json, contentType }) => {
 57	        response.writeHead(status, {
 58	          "content-type":
 59	            contentType ??
 60	            (json === undefined ? "text/plain" : "application/json"),
 61	        });
 62	        response.end(json === undefined ? body : JSON.stringify(json));
 63	      },
 64	    });
 65	  }
 66	}
