 10	function readEntities(body: unknown): Entity[] {
 11	  if (!isRecord(body) || !Array.isArray(body.entities)) {
 12	    throw new Error("Search returned an unexpected response. Try again.");
 13	  }
 14	
 15	  return body.entities.map((value: unknown) => {
 16	    if (
 17	      !isRecord(value) ||
 18	      typeof value.name !== "string" ||
 19	      typeof value.id !== "string" ||
 20	      (value.kind !== "MP" && value.kind !== "Funder") ||
 21	      (value.funder_kind !== null && typeof value.funder_kind !== "string")
 22	    ) {
 23	      throw new Error("Search returned an unexpected response. Try again.");
 24	    }
 25	    const source = value.match_source;
 26	    if (!isRecord(source))
 27	      throw new Error("Search returned an unexpected match source. Try again.");
 28	    let matchSource: SearchMatchSource;
 29	    switch (source.kind) {
 30	      case "name":
 31	        matchSource = { kind: "name" };
 32	        break;
 33	      case "alias":
 34	        if (typeof source.name !== "string" || !source.name.trim())
 35	          throw new Error(
 36	            "Search returned an unexpected match source. Try again.",
 37	          );
 38	        matchSource = { kind: "alias", name: source.name };
 39	        break;
 40	      default:
