    86	): Promise<Entity[]> {
    87	  const controller = new AbortController();
    88	  let timedOut = false;
    89	  const cancel = () => controller.abort();
    90	  signal.addEventListener("abort", cancel, { once: true });
    91	  if (signal.aborted) cancel();
    92	  const timeout = setTimeout(() => {
    93	    timedOut = true;
    94	    controller.abort();
    95	  }, searchConfiguration.timeoutMs);
    96	
    97	  try {
    98	    const params = new URLSearchParams({
    99	      term,
   100	      max_entries: String(searchConfiguration.maxEntriesPerType),
   101	      strictness: String(searchConfiguration.strictness),
   102	    });
   103	    const response = await fetch(`${origin}/search?${params}`, {
   104	      signal: controller.signal,
   105	    });
   106	    if (!response.ok) {
   107	      throw new Error(
   108	        "The search service is unavailable. Try again in a moment.",
   109	      );
   110	    }
   111	    const body: unknown = await response.json();
   112	    return readEntities(body);
   113	  } catch (error) {
   114	    if (timedOut) throw new Error("Search is taking too long. Try again.");
   115	    if (signal.aborted) throw error;
   116	    if (error instanceof TypeError || error instanceof SyntaxError) {
   117	      throw new Error(
   118	        "Couldn’t connect to search. Check your connection and try again.",
   119	      );
   120	    }
   121	    throw error;
   122	  } finally {
   123	    clearTimeout(timeout);
   124	    signal.removeEventListener("abort", cancel);
   125	  }
   126	}
     1	# Canonical search and alias matches
     2	
     3	Searching a recorded name or alias returns the canonical funder once, with the
     4	name that supplied the winning match recorded in `match_source`.
     5	
     6	## Sub-features
     7	
     8	- `unite` returns Unite the Union once, alongside broader matches at strictness 0.8.
     9	- `west mid` returns Unite through `UNITE The Union (West Midlands)` at strictness 0.8, ahead of the other accepted West Midlands matches.
    10	- `hsbc` returns one HSBC UK Bank plc entity at strictness 0.8.
    11	- `jahn` and `jahn mcdonnell` recover John McDonnell through people-search fallback when no primary people match.
    12	
    13	## How to get to it (user POV)
    14	
    15	Enter a term in the landing-page search box. Set the similarity slider to the
    16	regression default of 0.8. The browser sends the same `/search` request checked here.
    17	The public API also accepts GET requests with `term`, `strictness`, and
    18	`max_entries` query parameters.
    19	
    20	## Driving it with HTTP
    21	
    22	Preconditions: launch the snapshot API using the verify skill.
    23	
    24	- Run `./scripts/check-search-regression.py "$base_url" "$evidence_dir/http"`.
    25	- Require `PASS unite`, `PASS west-mid`, and `PASS hsbc`.
    26	- Inspect their `.request.txt`, `.response.json`, and `.diff.txt` artifacts. Each entity array must match the baseline after omitting IDs, including order, names, kinds, and match provenance.
    27	
    28	Run the opt-in people-search HTTP regression against the same read-only snapshot:
    29	
    30	```sh
    31	SEARCH_REGRESSION_DATABASE_URL="$DATABASE_URL" cargo test --package exposed --test integration loaded_data_people_search_regression -- --ignored
    32	```
    33	
    34	Require the test to pass. It checks that John McDonnell remains first for correct
    35	spelling and appears within the normal result limit for both misspelled queries.
    36	
    37	## Gotchas
    38	
    39	- The frontend and regression searches default to strictness 0.8.
    40	- All cases use the frontend's current limit of ten results per entity type.
    41	- A frozen database tests search deduplication by persisted ID, not upstream observation resolution.
    42	- This HTTP check does not prove slider behavior or rendering in the browser.
